args.query:
SELECT SUM(CASE WHEN plan='annual' THEN billed_amount/12 ELSE billed_amount END) AS mrr
FROM fct_subscriptions
WHERE is_active = True;

SELECT SUM(value) as active_users_prev_week FROM (
  SELECT value FROM "metric_active_users_week" WHERE metric_time BETWEEN DATE '2026-06-29' AND DATE '2026-07-05'
)

SELECT SUM(session_length_seconds) AS total_seconds
FROM fct_sessions
WHERE session_date BETWEEN DATE '2026-07-06' AND DATE '2026-07-12';
